+impl HorizontalTabStrip {
+    /// Only a cell inside a visible, painted tab is selectable.
+    pub fn hit_test(&self, x: u16, y: u16) -> Option<usize> {
+        self.tabs
+            .iter()
+            .find(|tab| tab.rect.width > 0 && tab.rect.contains((x, y).into()))
+            .map(|tab| tab.index)
+    }
+}
